# Generate oxide compositions for Materials Project query
import itertools

# Common metal elements that form oxides
metals = ['Li', 'Na', 'K', 'Mg', 'Ca', 'Sr', 'Ba', 'Al', 'Sc', 'Ti', 'V', 'Cr', 'Mn', 'Fe', 'Co', 'Ni', 'Cu', 'Zn', 'Ga', 'Y', 'Zr', 'Nb', 'Mo', 'Cd', 'In', 'Sn', 'La', 'Ce', 'Hf', 'Ta', 'W', 'Pb', 'Bi']

compositions = []

# Binary oxides (MO, M2O, MO2, M2O3, M3O4, etc.)
for metal in metals[:25]:  # Limit to first 25 metals
    for m_ratio in [1, 2, 3]:
        for o_ratio in [1, 2, 3, 4]:
            comp = f"{metal}{m_ratio}O{o_ratio}" if m_ratio > 1 else f"{metal}O{o_ratio}" if o_ratio > 1 else f"{metal}O"
            if comp not in compositions:
                compositions.append(comp)
                if len(compositions) >= 40:
                    break
        if len(compositions) >= 40:
            break
    if len(compositions) >= 40:
        break

print(f"Generated {len(compositions)} oxide compositions")
for i, comp in enumerate(compositions[:40], 1):
    print(f"{i}. {comp}")

# Save to file
with open('/home/alamparan/corral/ml/WORK_DIR_2/ml_oxides_trial_8/compositions.txt', 'w') as f:
    for comp in compositions[:40]:
        f.write(comp + '\n')
